window.KH_SURA(40, {"sura": "غافر", "n": 40, "ayat": {"1": "حم", "2": "تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْعَلِيمِ", "3": "غَافِرِ الذَّنْبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِ ذِي الطَّوْلِ لَا إِلَهَ إِلَّا هُوَ إِلَيْهِ الْمَصِيرُ", "4": "مَا يُجَادِلُ فِي آيَاتِ اللَّهِ إِلَّا الَّذِينَ كَفَرُوا فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِي الْبِلَادِ", "5": "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَالْأَحْزَابُ مِنْ بَعْدِهِمْ وَهَمَّتْ كُلُّ أُمَّةٍ بِرَسُولِهِمْ لِيَأْخُذُوهُ وَجَادَلُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ فَأَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ", "6": "وَكَذَلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذِينَ كَفَرُوا أَنَّهُمْ أَصْحَابُ النَّارِ", "7": "الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِ وَيَسْتَغْفِرُونَ لِلَّذِينَ آمَنُوا رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ", "8": "رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدْتَهُمْ وَمَنْ صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ", "9": "وَقِهِمُ السَّيِّئَاتِ وَمَنْ تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ وَذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ", "10": "إِنَّ الَّذِينَ كَفَرُوا يُنَادَوْنَ لَمَقْتُ اللَّهِ أَكْبَرُ مِنْ مَقْتِكُمْ أَنْفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى الْإِيمَانِ فَتَكْفُرُونَ", "11": "قَالُوا رَبَّنَا أَمَتَّنَا اثْنَتَيْنِ وَأَحْيَيْتَنَا اثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَى خُرُوجٍ مِنْ سَبِيلٍ", "12": "ذَلِكُمْ بِأَنَّهُ إِذَا دُعِيَ اللَّهُ وَحْدَهُ كَفَرْتُمْ وَإِنْ يُشْرَكْ بِهِ تُؤْمِنُوا فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ", "13": "هُوَ الَّذِي يُرِيكُمْ آيَاتِهِ وَيُنَزِّلُ لَكُمْ مِنَ السَّمَاءِ رِزْقًا وَمَا يَتَذَكَّرُ إِلَّا مَنْ يُنِيبُ", "14": "فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ", "15": "رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ يُلْقِي الرُّوحَ مِنْ أَمْرِهِ عَلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ لِيُنْذِرَ يَوْمَ التَّلَاقِ", "16": "يَوْمَ هُمْ بَارِزُونَ لَا يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَيْءٌ لِمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ", "17": "الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ بِمَا كَسَبَتْ لَا ظُلْمَ الْيَوْمَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ", "18": "وَأَنْذِرْهُمْ يَوْمَ الْآزِفَةِ إِذِ الْقُلُوبُ لَدَى الْحَنَاجِرِ كَاظِمِينَ مَا لِلظَّالِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ", "19": "يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ", "20": "وَاللَّهُ يَقْضِي بِالْحَقِّ وَالَّذِينَ يَدْعُونَ مِنْ دُونِهِ لَا يَقْضُونَ بِشَيْءٍ إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ", "21": "أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ كَانُوا مِنْ قَبْلِهِمْ كَانُوا هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَآثَارًا فِي الْأَرْضِ فَأَخَذَهُمُ اللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُمْ مِنَ اللَّهِ مِنْ وَاقٍ", "22": "ذَلِكَ بِأَنَّهُمْ كَانَتْ تَأْتِيهِمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَكَفَرُوا فَأَخَذَهُمُ اللَّهُ إِنَّهُ قَوِيٌّ شَدِيدُ الْعِقَابِ", "23": "وَلَقَدْ أَرْسَلْنَا مُوسَى بِآيَاتِنَا وَسُلْطَانٍ مُبِينٍ", "24": "إِلَى فِرْعَوْنَ وَهَامَانَ وَقَارُونَ فَقَالُوا سَاحِرٌ كَذَّابٌ", "25": "فَلَمَّا جَاءَهُمْ بِالْحَقِّ مِنْ عِنْدِنَا قَالُوا اقْتُلُوا أَبْنَاءَ الَّذِينَ آمَنُوا مَعَهُ وَاسْتَحْيُوا نِسَاءَهُمْ وَمَا كَيْدُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ", "26": "وَقَالَ فِرْعَوْنُ ذَرُونِي أَقْتُلْ مُوسَى وَلْيَدْعُ رَبَّهُ إِنِّي أَخَافُ أَنْ يُبَدِّلَ دِينَكُمْ أَوْ أَنْ يُظْهِرَ فِي الْأَرْضِ الْفَسَادَ", "27": "وَقَالَ مُوسَى إِنِّي عُذْتُ بِرَبِّي وَرَبِّكُمْ مِنْ كُلِّ مُتَكَبِّرٍ لَا يُؤْمِنُ بِيَوْمِ الْحِسَابِ", "28": "وَقَالَ رَجُلٌ مُؤْمِنٌ مِنْ آلِ فِرْعَوْنَ يَكْتُمُ إِيمَانَهُ أَتَقْتُلُونَ رَجُلًا أَنْ يَقُولَ رَبِّيَ اللَّهُ وَقَدْ جَاءَكُمْ بِالْبَيِّنَاتِ مِنْ رَبِّكُمْ وَإِنْ يَكُ كَاذِبًا فَعَلَيْهِ كَذِبُهُ وَإِنْ يَكُ صَادِقًا يُصِبْكُمْ بَعْضُ الَّذِي يَعِدُكُمْ إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ", "29": "يَاقَوْمِ لَكُمُ الْمُلْكُ الْيَوْمَ ظَاهِرِينَ فِي الْأَرْضِ فَمَنْ يَنْصُرُنَا مِنْ بَأْسِ اللَّهِ إِنْ جَاءَنَا قَالَ فِرْعَوْنُ مَا أُرِيكُمْ إِلَّا مَا أَرَى وَمَا أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ", "30": "وَقَالَ الَّذِي آمَنَ يَاقَوْمِ إِنِّي أَخَافُ عَلَيْكُمْ مِثْلَ يَوْمِ الْأَحْزَابِ", "31": "مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَالَّذِينَ مِنْ بَعْدِهِمْ وَمَا اللَّهُ يُرِيدُ ظُلْمًا لِلْعِبَادِ", "32": "وَيَاقَوْمِ إِنِّي أَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِ", "33": "يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُمْ مِنَ اللَّهِ مِنْ عَاصِمٍ وَمَنْ يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ", "34": "وَلَقَدْ جَاءَكُمْ يُوسُفُ مِنْ قَبْلُ بِالْبَيِّنَاتِ فَمَا زِلْتُمْ فِي شَكٍّ مِمَّا جَاءَكُمْ بِهِ حَتَّى إِذَا هَلَكَ قُلْتُمْ لَنْ يَبْعَثَ اللَّهُ مِنْ بَعْدِهِ رَسُولًا كَذَلِكَ يُضِلُّ اللَّهُ مَنْ هُوَ مُسْرِفٌ مُرْتَابٌ", "35": "الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ كَبُرَ مَقْتًا عِنْدَ اللَّهِ وَعِنْدَ الَّذِينَ آمَنُوا كَذَلِكَ يَطْبَعُ اللَّهُ عَلَى كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ", "36": "وَقَالَ فِرْعَوْنُ يَاهَامَانُ ابْنِ لِي صَرْحًا لَعَلِّي أَبْلُغُ الْأَسْبَابَ", "37": "أَسْبَابَ السَّمَاوَاتِ فَأَطَّلِعَ إِلَى إِلَهِ مُوسَى وَإِنِّي لَأَظُنُّهُ كَاذِبًا وَكَذَلِكَ زُيِّنَ لِفِرْعَوْنَ سُوءُ عَمَلِهِ وَصُدَّ عَنِ السَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِي تَبَابٍ", "38": "وَقَالَ الَّذِي آمَنَ يَاقَوْمِ اتَّبِعُونِ أَهْدِكُمْ سَبِيلَ الرَّشَادِ", "39": "يَاقَوْمِ إِنَّمَا هَذِهِ الْحَيَاةُ الدُّنْيَا مَتَاعٌ وَإِنَّ الْآخِرَةَ هِيَ دَارُ الْقَرَارِ", "40": "مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَى إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَالِحًا مِنْ ذَكَرٍ أَوْ أُنْثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ", "41": "وَيَاقَوْمِ مَا لِي أَدْعُوكُمْ إِلَى النَّجَاةِ وَتَدْعُونَنِي إِلَى النَّارِ", "42": "تَدْعُونَنِي لِأَكْفُرَ بِاللَّهِ وَأُشْرِكَ بِهِ مَا لَيْسَ لِي بِهِ عِلْمٌ وَأَنَا أَدْعُوكُمْ إِلَى الْعَزِيزِ الْغَفَّارِ", "43": "لَا جَرَمَ أَنَّمَا تَدْعُونَنِي إِلَيْهِ لَيْسَ لَهُ دَعْوَةٌ فِي الدُّنْيَا وَلَا فِي الْآخِرَةِ وَأَنَّ مَرَدَّنَا إِلَى اللَّهِ وَأَنَّ الْمُسْرِفِينَ هُمْ أَصْحَابُ النَّارِ", "44": "فَسَتَذْكُرُونَ مَا أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ", "45": "فَوَقَاهُ اللَّهُ سَيِّئَاتِ مَا مَكَرُوا وَحَاقَ بِآلِ فِرْعَوْنَ سُوءُ الْعَذَابِ", "46": "النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ", "47": "وَإِذْ يَتَحَاجُّونَ فِي النَّارِ فَيَقُولُ الضُّعَفَاءُ لِلَّذِينَ اسْتَكْبَرُوا إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنْتُمْ مُغْنُونَ عَنَّا نَصِيبًا مِنَ النَّارِ", "48": "قَالَ الَّذِينَ اسْتَكْبَرُوا إِنَّا كُلٌّ فِيهَا إِنَّ اللَّهَ قَدْ حَكَمَ بَيْنَ الْعِبَادِ", "49": "وَقَالَ الَّذِينَ فِي النَّارِ لِخَزَنَةِ جَهَنَّمَ ادْعُوا رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِنَ الْعَذَابِ", "50": "قَالُوا أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُمْ بِالْبَيِّنَاتِ قَالُوا بَلَى قَالُوا فَادْعُوا وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ", "51": "إِنَّا لَنَنْصُرُ رُسُلَنَا وَالَّذِينَ آمَنُوا فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْأَشْهَادُ", "52": "يَوْمَ لَا يَنْفَعُ الظَّالِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ اللَّعْنَةُ وَلَهُمْ سُوءُ الدَّارِ", "53": "وَلَقَدْ آتَيْنَا مُوسَى الْهُدَى وَأَوْرَثْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ", "54": "هُدًى وَذِكْرَى لِأُولِي الْأَلْبَابِ", "55": "فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَاسْتَغْفِرْ لِذَنْبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِيِّ وَالْإِبْكَارِ", "56": "إِنَّ الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ إِنْ فِي صُدُورِهِمْ إِلَّا كِبْرٌ مَا هُمْ بِبَالِغِيهِ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ", "57": "لَخَلْقُ السَّمَاوَاتِ وَالْأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "58": "وَمَا يَسْتَوِي الْأَعْمَى وَالْبَصِيرُ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَلَا الْمُسِيءُ قَلِيلًا مَا تَتَذَكَّرُونَ", "59": "إِنَّ السَّاعَةَ لَآتِيَةٌ لَا رَيْبَ فِيهَا وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ", "60": "وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ", "61": "اللَّهُ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ", "62": "ذَلِكُمُ اللَّهُ رَبُّكُمْ خَالِقُ كُلِّ شَيْءٍ لَا إِلَهَ إِلَّا هُوَ فَأَنَّى تُؤْفَكُونَ", "63": "كَذَلِكَ يُؤْفَكُ الَّذِينَ كَانُوا بِآيَاتِ اللَّهِ يَجْحَدُونَ", "64": "اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا وَالسَّمَاءَ بِنَاءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِ ذَلِكُمُ اللَّهُ رَبُّكُمْ فَتَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ", "65": "هُوَ الْحَيُّ لَا إِلَهَ إِلَّا هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "66": "قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَاتُ مِنْ رَبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ", "67": "هُوَ الَّذِي خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوا أَشُدَّكُمْ ثُمَّ لِتَكُونُوا شُيُوخًا وَمِنْكُمْ مَنْ يُتَوَفَّى مِنْ قَبْلُ وَلِتَبْلُغُوا أَجَلًا مُسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ", "68": "هُوَ الَّذِي يُحْيِي وَيُمِيتُ فَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ", "69": "أَلَمْ تَرَ إِلَى الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ أَنَّى يُصْرَفُونَ", "70": "الَّذِينَ كَذَّبُوا بِالْكِتَابِ وَبِمَا أَرْسَلْنَا بِهِ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ", "71": "إِذِ الْأَغْلَالُ فِي أَعْنَاقِهِمْ وَالسَّلَاسِلُ يُسْحَبُونَ", "72": "فِي الْحَمِيمِ ثُمَّ فِي النَّارِ يُسْجَرُونَ", "73": "ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنْتُمْ تُشْرِكُونَ", "74": "مِنْ دُونِ اللَّهِ قَالُوا ضَلُّوا عَنَّا بَلْ لَمْ نَكُنْ نَدْعُو مِنْ قَبْلُ شَيْئًا كَذَلِكَ يُضِلُّ اللَّهُ الْكَافِرِينَ", "75": "ذَلِكُمْ بِمَا كُنْتُمْ تَفْرَحُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنْتُمْ تَمْرَحُونَ", "76": "ادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ", "77": "فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ", "78": "وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ مِنْهُمْ مَنْ قَصَصْنَا عَلَيْكَ وَمِنْهُمْ مَنْ لَمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَنْ يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ فَإِذَا جَاءَ أَمْرُ اللَّهِ قُضِيَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ", "79": "اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَنْعَامَ لِتَرْكَبُوا مِنْهَا وَمِنْهَا تَأْكُلُونَ", "80": "وَلَكُمْ فِيهَا مَنَافِعُ وَلِتَبْلُغُوا عَلَيْهَا حَاجَةً فِي صُدُورِكُمْ وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ", "81": "وَيُرِيكُمْ آيَاتِهِ فَأَيَّ آيَاتِ اللَّهِ تُنْكِرُونَ", "82": "أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ كَانُوا أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَآثَارًا فِي الْأَرْضِ فَمَا أَغْنَى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ", "83": "فَلَمَّا جَاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ فَرِحُوا بِمَا عِنْدَهُمْ مِنَ الْعِلْمِ وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "84": "فَلَمَّا رَأَوْا بَأْسَنَا قَالُوا آمَنَّا بِاللَّهِ وَحْدَهُ وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ", "85": "فَلَمْ يَكُ يَنْفَعُهُمْ إِيمَانُهُمْ لَمَّا رَأَوْا بَأْسَنَا سُنَّتَ اللَّهِ الَّتِي قَدْ خَلَتْ فِي عِبَادِهِ وَخَسِرَ هُنَالِكَ الْكَافِرُونَ"}, "units": [{"aya": 1, "title": "في معنى قوله: ﴿حم﴾", "tabari": {"page": "20/274", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هي حروف مقطعة من اسم الله، الذي هو الرحمن ، وهو، وهو الحاء والميم منه", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": []}, {"n": 2, "t": "هو قسم أقسمه الله، وهو اسم من أسماء الله", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["السدي", "تابعي"]], "athar": []}, {"n": 3, "t": "بل هو اسم من أسماء القرآن", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": []}, {"n": 4, "t": "هو حروف هجاء", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 5, "t": "بل هو اسم. واحتجوا لقولهم ذلك بقول شريح بن أوفى العبسي :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5661, "mi": 0, "aya": 0, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 166 - 167", "qawl": "احتجوا لقولهم", "nass": "وهذا إسناد صحيح", "qawaid": [], "tabi": ""}, {"taliq": 5661, "mi": 0, "aya": 0, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 275 - 276", "qawl": "", "nass": "وحدثت عن معمر بن المثنى، أنه قال: قال يونس -يعني: الجرمي-: ومن قال هذا القول فهو منكر عليه؛ لأن السورة {حم} ساكنة الحروف، فخرجت مخرج التهجي، وهذه أسماء سور خرجت متحركات، وإذا سميت سورة بشيء من هذه الأحرف المجزومة دخله الإعراب. والقول في ذلك عندي نظير القول في أخواتها، وقد بينا ذلك، في قوله: {الم} [البقرة: 1]، ففي ذلك كفاية عن إعادته في هذا الموضع، إذ كان القول في {حم} وجميع ما جاء في القرآن على هذا الوجه، أعني: حروف التهجي قولا واحدا", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["040_001_1.png"], "pages": [449], "n": 3, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 3, "title": "تأويل: ﴿ذي الطول﴾", "tabari": {"page": "20/279", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ذي الطول﴾. يقول: ذى الفضل والنعم المبسوطة على من شاء من خلقه. يقال منه: إن فلانا لذو طول على أصحابه. إذا كان ذا فضل عليهم.", "taqdim": 1, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [67800, 67804, 67805, 67807, 67808, 67812, 67816]}, {"n": 2, "t": "الطول: القدرة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [67815]}]}, "mawaqif": [], "mushid": {"i": 2, "imgs": ["040_002_1.png"], "pages": [449], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "تأويل: ﴿وهمت كل أمة برسولهم ليأخذوه﴾", "tabari": {"page": "20/281", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وهمت كل أمة برسولهم ليأخذوه﴾. يقول تعالى ذكره: وهمت كل أمة من هذه الأمم المكذبة رسلها، المتحزبة على أنبيائها، برسولهم الذي أرسل إليهم، ليأخذوه فيقتلوه.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿برسولهم﴾، وقد قيل قبل : ﴿كل أمة﴾. فوجهت الهاء والميم إلى الرجل دون لفظ الأمة، وقد ذكر أن ذلك في قراءة عبد الله: (برسولها) . بمعنى : برسول الأمة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "في وجه دخول هذه اللام في قوله: ﴿لمقت الله أكبر﴾", "tabari": {"page": "20/289", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: دخلت لتؤذن أن ما بعدها ائتناف ، وأنها لام اليمين.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هي لام الابتداء، كأن ﴿ينادون﴾: يقال لهم؛ لأن النداء قول. قال: ومثله في الإعراب يقال: لزيد أفضل من عمرو", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "المعنى فيه: ينادون أن مقت الله إياكم. ولكن اللام تكفى من أن تقول في الكلام: ناديت أن زيدا قائم. قال: ومثله قوله: ﴿ثم بدا لهم من بعد ما رأوا الآيات ليسجننه حتى حين﴾ [يوسف: ٣٥]. اللام بمنزلة \"أن\" في كل كلام ضارع القول، مثل: ينادون ويخبرون، وأشباه ذلك", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "هذه لام اليمين، تدخل مع الحكاية، وما ضارع الحكاية؛ لتدل على أن ما بعدها ائتناف . قال: ولا يجوز في جوابات الأيمان أن تقوم مقام اليمين؛ لأن اللام - كانت معها النون أو لم تكن - اكتفى بها من اليمين؛ لأنها لا تقع إلا معها", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "تأويل: ﴿ربنا أمتنا اثنتين وأحييتنا اثنتين﴾", "tabari": {"page": "20/292", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ربنا أمتنا اثنتين وأحييتنا اثنتين﴾. قد أتينا عليه في سورة \"البقرة\"، فأغنى ذلك عن إعادته في هذا الموضع ، ولكنا نذكر بعض ما قال بعضهم فيه:", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "ثنا أحمد، قال: ثنا أسباط، عن السدي قوله: ﴿أمتنا اثنتين وأحييتنا اثنتين﴾. قال: أميتوا في الدنيا، ثم أحيوا في قبورهم فسئلوا أو خوطبوا، ثم أميتوا في قبورهم، ثم أحيوا في الآخرة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿ربنا أمتنا اثنتين وأحييتنا اثنتين﴾. قال: خلقهم من ظهر آدم، حين أخذ عليهم الميثاق. وقرأ: ﴿وإذ أخذ ربك من بني آدم من ظهورهم ذريتهم ﴾، فقرأ حتى بلغ: ﴿المبطلون﴾ [الأعراف: ١٧٢]. قال: فنساهم الفعل، وأخذ عليهم الميثاق. قال: وانتزع ضلعا من أضلاع آدم القصرى، فخلق منه حواء. ذكره عن النبي ﷺ. قال: وذلك قول الله: ﴿ياأيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة وخلق منها زوجها وبث منهما ", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5666, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 426", "qawl": "الثاني", "nass": "", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5666, "mi": 1, "aya": 11, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "12/ 176", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 5666, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "والأول أثبت الأقوال", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5666, "mi": 1, "aya": 11, "alam": "ابن تيمية", "fil": "رجحه", "kind": "ترجيح", "ref": "5/ 431", "qawl": "", "nass": "والصحيح أن هذه الآية كقوله: {وكنتم أمواتا فأحياكم ثم يميتكم ثم يحييكم} [البقرة: 28]، فالموتة الأولى قبل هذه الحياة، والموتة الثانية بعد هذه الحياة، وقوله تعالى: {ثم يحييكم} بعد الموت: قال تعالى: {منها خلقناكم وفيها نعيدكم ومنها نخرجكم تارة أخرى} وقال: {قال فيها تحيون وفيها تموتون ومنها تخرجون} [الأعراف: 25]", "qawaid": ["القرآن والنظائر"], "tabi": "ابن عطية"}, {"taliq": 5666, "mi": 1, "aya": 11, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "12/ 176", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن تيمية"}], "mushid": {"i": 3, "imgs": ["040_003_1.png", "040_003_2.png"], "pages": [449, 450], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5666, "masala": "قوله تعالى: {قالوا ربنا أمتنا اثنتين وأحييتنا اثنتين}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه خلقهم أمواتا في أصلاب آبائهم، ثم أحياهم بإخراجهم، ثم أماتهم عند انقضاء آجالهم، ثم أحياهم للبعث", "ashab": "", "athar": []}, {"n": 2, "t": "أنه أحياهم نسما عند أخذ العهد عليهم وقت أخذهم من صلب آدم عليه السلام، ثم أماتهم بعد ذلك، ثم أحياهم في الدنيا، ثم أماتهم، ثم أحياهم", "ashab": "", "athar": []}, {"n": 3, "t": "أنه أحياهم في الدنيا، ثم أماتهم، ثم أحياهم في القبر وقت سؤال منكر ونكير، ثم أماتهم فيه، ثم أحياهم في الحشر", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن عطية", "d"], ["ابن كثير", "q"]], "1": [["ابن عطية", "r"], ["ابن تيمية", "r"], ["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"], "ابن تيمية": ["القرآن والنظائر"]}, "rulesD": {"ابن عطية": ["ظاهر الآية ولفظها"]}}}, {"aya": 15, "title": "في معنى الروح في هذا الموضع ﴿يلقي الروح من أمره على من يشاء من عباده﴾", "tabari": {"page": "20/294", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى به الوحي", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [67904, 67915]}, {"n": 2, "t": "عنى به القرآن والكتاب", "taqdim": 0, "n_athar": 2, "qailun": [["الضحاك", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [67903, 67907, 67918]}, {"n": 3, "t": "عنى به النبوة", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67905, 67916]}]}, "mawaqif": [{"taliq": 5670, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 428", "qawl": "", "nass": "ويحتمل أن يكون إلقاء الروح عاما لكل ما ينعم الله به على عباده المهتدين في تفهيمه الإيمان والمعتقدات الشرعية", "qawaid": [], "tabi": ""}], "mushid": {"i": 4, "imgs": ["040_004_1.png"], "pages": [450], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5670, "masala": "المراد بالروح", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه القرآن والكتاب", "ashab": "", "athar": []}, {"n": 2, "t": "النبوة", "ashab": "", "athar": []}, {"n": 3, "t": "الوحي", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "تسمية يوم القيامة بيوم التلاق", "mawsua": {"taliq": 5672, "masala": "تسمية يوم القيامة بيوم التلاق", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "لأنه يلتقي فيه أهل السماء وأهل الأرض", "ashab": "", "athar": []}, {"n": 2, "t": "لأنه يلتقي فيه الأولون والآخرون", "ashab": "", "athar": []}, {"n": 3, "t": "يلتقي فيه الخلق والخالق", "ashab": "", "athar": []}, {"n": 4, "t": "لأنه يلتقي فيه الظالم والمظلوم", "ashab": "", "athar": []}, {"n": 5, "t": "لأنه يلقى المرء فيه عمله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5672, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 428", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5672, "mi": 1, "aya": 15, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "12/ 179", "qawl": "", "nass": "وقد يقال: إن يوم القيامة هو يشمل هذا كله، ويشمل أن كل عامل سيلقى ما عمله من خير وشر", "qawaid": [], "tabi": ""}, {"taliq": 5672, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 428", "qawl": "الثالث", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 18, "title": "قوله: {إذ القلوب لدى الحناجر}", "mawsua": {"taliq": 5673, "masala": "قوله: {إذ القلوب لدى الحناجر}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون حقيقة يوم القيامة من انتقال قلوب البشر إلى حناجرهم وتبقى حياتهم، بخلاف الدنيا التي لا تبقى لأحد فيها حياة مع تنقل قلبه", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون تجوزا عبر به عما يجده الإنسان من الجزع وصعود نفسه وتضايق حنجرته بصعود قلبه، وهذا كما تقول العرب: كادت نفسي أن تخرج. وهذا المعنى يجده المفرط الجزع كالذي يساق إلى القتل ونحوه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5673, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 431", "qawl": "العرب", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 26, "title": "قراءة قوله: {أو أن يظهر في الأرض الفساد}", "mawsua": {"taliq": 5677, "masala": "قراءة قوله: {أو أن يظهر في الأرض الفساد}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{أو أن يظهر في الأرض الفساد}", "ashab": "", "athar": []}, {"n": 2, "t": "أو أن يظهر في الأرض الفساد", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5677, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 435", "qawl": "", "nass": "أن فرعون على القراءة الأولى خاف أمرين، وعلى الثانية خاف أمرا واحدا", "qawaid": [], "tabi": ""}, {"taliq": 5677, "mi": 1, "aya": 26, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 184", "qawl": "", "nass": "أن الأكثرين على القراءة الأولى", "qawaid": [], "tabi": ""}, {"taliq": 5677, "mi": 1, "aya": 26, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 309", "qawl": "", "nass": "والصواب من القول في ذلك عندنا: أنهما قراءتان مشهورتان في قراءة الأمصار، متقاربتا المعنى، وذلك أن الفساد إذا أظهره مظهر كان ظاهرا، وإذا ظهر فبإظهار مظهر يظهر، ففي القراءة بإحدى القراءتين في ذلك دليل على صحة معنى الأخرى، وأما القراءة في: {أو أن يظهر} بالألف وبحذفها، فإنهما أيضا متقاربتا المعنى؛ وذلك أن الشيء إذا بدل إلى خلافه فلا شك أن خلافه المبدل إليه الأول هو الظاهر دون المبدل، فسواء عطف على خبره عن خوفه من موسى أن يبدل دينهم بالواو أو ب {أو}؛ لأن تبديل دينهم كان عنده هو ظهور الفساد، وظهور الفساد كان عنده هو تبديل الدين", "qawaid": ["القراءة ورسم المصحف", "صحة المعنى وتقاربه"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف", "صحة المعنى وتقاربه"]}, "rulesD": {}}}, {"aya": 28, "title": "في هذا الرجل المؤمن", "tabari": {"page": "20/311", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب عندى القول الذي قاله السدي، من أن الرجل المؤمن كان من آل فرعون، قد أصغى لكلامه واستمع منه ما قاله، وتوفف عن قتل موسى عند نهيه عن قتله وقيله ما قال، وقال له: ما أريكم إلا ما أرى، وما أهديكم إلا سبيل الرشاد. ولو كان إسرائيليا لكان حريا أن يعاجل هذا القائل له ولملئه ما قال، بالعقوبة على قوله؛ لأنه لم يكن يستنصح بني إسرائيل؛ لاعتداده إياهم أعداء له، فكيف بقوله عن قتل موسى لو وجد إليه سبيلا، ولكنه لما كان من ملإ قومه، استمع قوله وكف عما كان هم به في موسى.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "كان من قوم فرعون غير أنه كان قد آمن بموسى، وكان يسر إيمانه من فرعون وقومه خوفا على نفسه", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67983, 67992, 67993]}, {"n": 2, "t": "بل كان الرجل إسرائيليا، ولكنه كان يكتم إيمانه من آل فرعون", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5678, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "ذكره", "kind": "نقل", "ref": "20/ 311", "qawl": "", "nass": "أنه كان إسرائيليا، ولكنه كان يكتم إيمانه من آل فرعون", "qawaid": [], "tabi": ""}, {"taliq": 5678, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 436", "qawl": "", "nass": "أنه كان إسرائيليا، ولكنه كان يكتم إيمانه من آل فرعون", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5678, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "ذكره", "kind": "نقل", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5678, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5678, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 312", "qawl": "الأول", "nass": "لأن فرعون انفعل لكلامه واستمعه، وكف عن قتل موسى عليه السلام، ولو كان إسرائيليا لأوشك أن يعاجل بالعقوبة؛ لأنه منهم", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5678, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "وكذا", "kind": "موافقة", "ref": "7/ 437", "qawl": "", "nass": "والأول أصح، ولم يكن لأحد من بني إسرائيل أن يتكلم بمثل هذا عند فرعون", "qawaid": ["الدلالة العقلية"], "tabi": "ابن جرير"}], "mushid": {"i": 5, "imgs": ["040_005_1.png"], "pages": [450], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5678, "masala": "هذا الرجل المؤمن", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه كان من قوم فرعون، غير أنه كان قد آمن بموسى، وكان يسر إيمانه من فرعون وقومه خوفا على نفسه، وعليه يكون الوقف على قوله: {من آل فرعون}؛ لأن ذلك خبر متناه قد تم، و {يكتم} في موضع الصفة دون تقديم وتأخير", "ashab": "", "athar": []}, {"n": 2, "t": "أنه كان إسرائيليا، ولكنه كان يكتم إيمانه من آل فرعون", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"], "ابن عطية": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 28, "title": "في معنى الإسراف الذي ذكره المؤمن في هذا الموضع ﴿وإن يك كاذبا فعليه كذبه﴾", "tabari": {"page": "20/313", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن يقال: إن الله أخبر عن هذا المؤمن أنه عم بقوله: ﴿إن الله لا يهدي من هو مسرف كذاب﴾. والشرك من الإسراف، وسفك الدم بغير حق من الإسراف، وقد كان مجتمعا في فرعون الأمران كلاهما، فالحق أن يعم ذلك، كما أخبر جل ثناؤه عن قائله، أنه عم القول بذلك.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى به الشرك، وأراد: إن الله لا يهدى من هو مشرك به، مفتر عليه", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [67991]}, {"n": 2, "t": "عنى به من هو قتال سفاك للدماء بغير حق", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67983, 67992, 67993]}]}, "mawaqif": [{"taliq": 5680, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 313 - 314", "qawl": "العموم", "nass": "والصواب من القول في ذلك أن يقال: إن الله أخبر عن هذا المؤمن أنه عم بقوله: {إن الله لا يهدي من هو مسرف كذاب}، والشرك من الإسراف، وسفك الدم بغير حق من الإسراف، وقد كان مجتمعا في فرعون الأمران كلاهما، فالحق أن يعم ذلك كما أخبر -جل ثناؤه- عن قائله أنه عم القول بذلك", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["040_006_1.png"], "pages": [450], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5680, "masala": "المراد بالإسراف", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الشرك", "ashab": "", "athar": []}, {"n": 2, "t": "أنه عني به: من هو قتال سفاك للدماء بغير حق", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "قوله: {يصبكم بعض الذي يعدكم}", "mawsua": {"taliq": 5679, "masala": "قوله: {يصبكم بعض الذي يعدكم}", "sigha": "خلاف مصرَّح به", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن {بعض} بمعنى: كل", "ashab": "أبي عبيده وغيره", "athar": []}, {"n": 2, "t": "أنه إلزام للحجة بأيسر ما في الأمر، وليس فيه نفي إضافة الكل", "ashab": "الزجاج", "athar": []}, {"n": 3, "t": "أن المعنى: يصبكم بعض العذاب الذي يذكر، وذلك كاف في هلاككم", "ashab": "", "athar": []}, {"n": 4, "t": "أن المعنى: أراد ببعض ما يعدكم: عذاب الدنيا؛ لأنه بعض عذاب الآخرة، أي: وتصيرون بعد ذلك إلى الباقي، وفي البعض كفاية في الإهلاك. ثم قال: «ويظهر لي أن المعنى: يصبكم القسم الواحد مما يعد به، وذلك هو بعض ما يعد؛ لأنه عليه السلام وعدهم إن آمنوا بالنعيم، وإن كفروا بالعذاب، فإن كان صادقا فالعذاب بعض ما وعد به", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5679, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 437 - 438", "qawl": "", "nass": "ويظهر لي أن المعنى: يصبكم القسم الواحد مما يعد به، وذلك هو بعض ما يعد؛ لأنه عليه السلام وعدهم إن آمنوا بالنعيم، وإن كفروا بالعذاب، فإن كان صادقا فالعذاب بعض ما وعد به", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 30, "title": "المراد بقوله: {وقال الذي آمن}", "mawsua": {"taliq": 5683, "masala": "المراد بقوله: {وقال الذي آمن}", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه هو المؤمن المذكور أولا، قص الله تعالى أقاويله إلى آخر الآيات", "ashab": "جمهور المفسرين»", "athar": []}, {"n": 2, "t": "أنه موسى عليه السلام", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5683, "mi": 1, "aya": 30, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 436", "qawl": "", "nass": "أنه هو المؤمن المذكور أولا، قص الله تعالى أقاويله إلى آخر الآيات، ونسبه لجمهور المفسرين", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 32, "title": "قراءة قوله: {يوم التناد}", "mawsua": {"taliq": 5684, "masala": "قراءة قوله: {يوم التناد}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{يوم التناد} بتخفيف الدال، وترك إثبات الياء", "ashab": "", "athar": []}, {"n": 2, "t": "{يوم التناد} بتشديد الدال", "ashab": "", "athar": []}, {"n": 3, "t": "{التنادي} بتخفيف الدال، وإثبات الياء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5684, "mi": 1, "aya": 32, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 316 - 319", "qawl": "", "nass": "من الند", "qawaid": [], "tabi": ""}, {"taliq": 5684, "mi": 1, "aya": 32, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 319 - 320", "qawl": "", "nass": "وذلك أن ذلك هو القراءة التي عليها الحجة مجمعة من قرأة الأمصار، وغير جائز خلافها فيما جاءت به نقلا", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 32, "title": "التناد المشار إليه", "mawsua": {"taliq": 5685, "masala": "التناد المشار إليه", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه نداء أهل الجنة أهل النار: {فهل وجدتم ما وعد ربكم حقا} [الأعراف: 44]، ونداء أهل النار لهم: {أفيضوا علينا من الماء} [الأعراف: 50]", "ashab": "", "athar": []}, {"n": 2, "t": "أنه التنادي الذي يكون عند نفخة الفزع ينادي الناس بعضهم بعضا", "ashab": "", "athar": []}, {"n": 3, "t": "أنه إذا سمع الناس زفير جهنم وشهيقها ندوا فرارا منها في الأرض، فلا يتوجهون قطرا من أقطار الأرض إلا رأوا ملائكة، فيرجعون من حيث جاءوا", "ashab": "", "athar": []}, {"n": 4, "t": "أنه النداء الذي يتضمنه قوله تعالى: {يوم ندعوا كل أناس بإمامهم} [الإسراء: 71]", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5685, "mi": 1, "aya": 32, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 440", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5685, "mi": 1, "aya": 32, "alam": "ابن كثير", "fil": "ذكره", "kind": "نقل", "ref": "12/ 190", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 5685, "mi": 1, "aya": 32, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وهو قول حسن جيد", "qawaid": [], "tabi": ""}, {"taliq": 5685, "mi": 1, "aya": 32, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "", "qawl": "", "nass": "ويحتمل أن يكون المراد: التذكير بكل نداء في القيامة فيه مشقة على الكفار والعصاة ولها أجوبة بنداء، وهي كثيرة، منها ما ذكرناه، ومنها: يا أهل النار خلود لا موت، يا أهل الجنة خلود لا موت، ومنها: نداء أهل الغدرات، والنداء {لمقت الله} [غافر: 10]، والنداء {لمن الملك اليوم} [غافر: 16]، إلى غير ذلك", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 33, "title": "معنى قوله: {يوم تولون مدبرين}", "mawsua": {"taliq": 5686, "masala": "معنى قوله: {يوم تولون مدبرين}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هربا في الأرض من الفزع", "ashab": "", "athar": []}, {"n": 2, "t": "انصرافهم إلى النار", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5686, "mi": 1, "aya": 33, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 320", "qawl": "الأول", "nass": "وأولى القولين في ذلك بالصواب القول الذي روي عن رسول الله صلى الله عليه وسلم -حديث أبي هريرة في تفسير آية: {ويا قوم إني أخاف عليكم يوم التناد} -، وإن كان الذي قاله قتادة في ذلك غير بعيد من الحق، وبه قال جماعة من أهل التأويل", "qawaid": ["السنة"], "tabi": ""}, {"taliq": 5686, "mi": 1, "aya": 33, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 441", "qawl": "", "nass": "تفرون هروبا من الفزع، وعلى بعضها: تفرون مدبرين إلى النار", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السنة"]}, "rulesD": {}}}, {"aya": 35, "title": "قراءة قوله: {على كل قلب متكبر}", "mawsua": {"taliq": 5688, "masala": "قراءة قوله: {على كل قلب متكبر}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{كل قلب متكبر}", "ashab": "", "athar": []}, {"n": 2, "t": "(قلب كل متكبر)", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5688, "mi": 1, "aya": 35, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 323 - 324", "qawl": "", "nass": "القلب", "qawaid": ["اللغة"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 36, "title": "في معنى الأسباب في هذا الموضع ﴿وقال فرعون ياهامان ابن لي صرحا لعلي أبلغ الأسباب أسباب السماوات فأطلع إلى إله موسى وإني لأ﴾", "tabari": {"page": "20/324", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "أسباب السماوات: طرقها", "taqdim": 0, "n_athar": 2, "qailun": [["أبي صالح", "تابعي"], ["السدي", "تابعي"]], "athar": [68053, 68055]}, {"n": 2, "t": "عنى بأسباب السماوات أبواب السماوات", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [68048, 68054]}, {"n": 3, "t": "بل عنى به منزل السماء", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [68052]}]}, "mawaqif": [{"taliq": 5691, "mi": 1, "aya": 36, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "20/ 326", "qawl": "الجمع بين", "nass": "أولى الأقوال بالصواب في ذلك أن يقال: معناه: لعلي أبلغ من أسباب السموات أسبابا أتسبب بها إلى رؤية إله موسى؛ طرقا كانت تلك الأسباب منها، أو أبوابا، أو منازل، أو غير ذلك", "qawaid": ["اللغة", "العموم"], "tabi": ""}, {"taliq": 5691, "mi": 1, "aya": 36, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 443", "qawl": "", "nass": "وقيل: عنى: لعله يجد مع قربه من السماء سببا يتعلق به", "qawaid": [], "tabi": ""}], "mushid": {"i": 8, "imgs": ["040_008_1.png"], "pages": [451], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5691, "masala": "معنى أسباب السموات", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه طرقها", "ashab": "", "athar": []}, {"n": 2, "t": "أبوابها", "ashab": "", "athar": []}, {"n": 3, "t": "أنه عني به: منزل السماء", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "قال بـالجمع بين"]], "rules": {"ابن جرير": ["اللغة", "العموم"]}, "rulesD": {}}}, {"aya": 43, "title": "تأويل: ﴿وأن مردنا إلى الله﴾", "tabari": {"page": "20/334", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وأن مردنا إلى الله﴾. يقول: وأن مرجعنا ومنقلبنا بعد مماتنا إلى الله، ﴿وأن المسرفين هم أصحاب النار﴾. يقول: وأن المشركين بالله المتعدين حدوده، القتلة النفوس التي حرم الله قتلها، هم أصحاب نار جهنم، عند مرجعنا إلى الله.", "taqdim": 1, "n_athar": 4, "qailun": [["مجاهد", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [68083, 68091, 68096]}, {"n": 2, "t": "هم المشركون", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [68084, 68085, 68094]}]}, "mawaqif": [{"taliq": 5696, "mi": 1, "aya": 43, "alam": "ابن جرير", "fil": "جمع", "kind": "توجيه", "ref": "20/ 333", "qawl": "", "nass": "{وأن المسرفين هم أصحاب النار} يقول: وإن المشركين بالله المتعدين حدوده، القتلة النفوس التي حرم الله قتلها، هم أصحاب نار جهنم عند مرجعنا إلى الله. وبنحو الذي قلنا في ذلك قال أهل التأويل على اختلاف منهم في معنى المسرفين في هذا الموضع", "qawaid": ["أقوال السلف", "السياق"], "tabi": ""}], "mushid": {"i": 9, "imgs": ["040_009_1.png"], "pages": [451], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5696, "masala": "المسرفين", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنهم سفاكو الدماء بغير حق", "ashab": "", "athar": []}, {"n": 2, "t": "المشركون", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 46, "title": "تأويل: ﴿النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعة أدخلوا آل فرعون أشد العذاب﴾", "tabari": {"page": "20/339", "sarih": 0, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر أن آل فرعون يعرضون على النار غدوا وعشيا. وجائز أن يكون ذلك العرض على النار على نحو ما ذكرناه عن الهزيل بن شرحبيل ومن قال مثل قوله، وأن يكون كما قال قتادة، ولا خبر بذلك يوجب الحجة بأن ذلك المعني به؛ فلا قول في ذلك إلا ما دل عليه ظاهر القرآن، وهو أنهم يعرضون على النار غدوا وعشيا. وأصل الغدو والعشى مصادر جعلت أوقاتا.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى بقوله: ﴿النار يعرضون عليها﴾] ، أنهم لما هلكوا وغرقهم الله، جعلت أرواحهم في أجواف طير سود، فهى تعرض على النار كل يوم مرتين؛ ﴿غدوا وعشيا﴾ إلى أن تقوم الساعة.", "taqdim": 1, "n_athar": 4, "qailun": [["الهزيل بن شرحبيل", ""], ["السدي", "تابعي"]], "athar": [68111, 68120]}, {"n": 2, "t": "عنى بذلك: أنهم يعرضون على منازلهم في النار؛ تعذيبا لهم، غدوا وعشيا", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [68112, 68117, 68118]}]}, "mawaqif": [{"taliq": 5699, "mi": 1, "aya": 46, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 339", "qawl": "", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر أن آل فرعون يعرضون على النار غدوا وعشيا. وجائز أن يكون ذلك العرض على النار على نحو ما ذكرناه عن الهزيل بن شرحبيل ومن قال مثل قوله، وأن يكون كما قال قتادة، ولا خبر يوجب الحجة بأن ذلك المعني به؛ فلا قول في ذلك إلا ما دل عليه ظاهر القرآن، وهم أنهم يعرضون على النار غدوا وعشيا", "qawaid": [], "tabi": ""}], "mushid": {"i": 10, "imgs": ["040_010_1.png"], "pages": [451], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5699, "masala": "المراد بقوله: {النار يعرضون عليها غدوا وعشيا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "تجعل أرواحهم في قبورهم في أجواف طير سود، وتعرض على النار كل يوم مرتين إلى أن تقوم الساعة", "ashab": "", "athar": []}, {"n": 2, "t": "يعرضون في قبورهم على منازلهم في النار تعذيبا لهم غدوا وعشيا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 46, "title": "قراءة قوله: {أدخلوا آل فرعون أشد العذاب}", "mawsua": {"taliq": 5700, "masala": "قراءة قوله: {أدخلوا آل فرعون أشد العذاب}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{أدخلوا} بقطع الألف", "ashab": "", "athar": []}, {"n": 2, "t": "ادخلوا» بوصلها", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5700, "mi": 1, "aya": 46, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 340", "qawl": "", "nass": "والصواب من القول في ذلك عندي أن يقال: إنهما قراءتان معروفتان، متقاربتا المعنى، قد قرأ بكل واحدة منهما جماعة من القراء؛ فبأيتهما قرأ القارئ فمصيب", "qawaid": ["القراءة ورسم المصحف", "صحة المعنى وتقاربه"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 67, "title": "بلوغ الأشد", "mawsua": {"taliq": 5711, "masala": "بلوغ الأشد", "sigha": "حكاية خلاف", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "ثلاثون", "ashab": "", "athar": []}, {"n": 2, "t": "ستة وثلاثون", "ashab": "", "athar": []}, {"n": 3, "t": "أربعون", "ashab": "", "athar": []}, {"n": 4, "t": "ستة وأربعون", "ashab": "", "athar": []}, {"n": 5, "t": "عشرون", "ashab": "", "athar": []}, {"n": 6, "t": "ثمانية عشر", "ashab": "", "athar": []}, {"n": 7, "t": "خمسة عشر", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5711, "mi": 0, "aya": 67, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 455", "qawl": "", "nass": "وهذه الأقوال الأخيرة ضعيفة في الأشد", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 69, "title": "في الذين عنوا بهذه الآية", "tabari": {"page": "20/360", "sarih": 1, "tarjih": "والصواب من القول في ذلك ما قاله ابن زيد، وقد بين الله حقيقة ذلك بقوله: ﴿الذين كذبوا بالكتاب وبما أرسلنا به رسلنا﴾.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى بها أهل القدر", "taqdim": 0, "n_athar": 3, "qailun": [["محمد بن سيرين", "تابعي"], ["ابن سيرين", "تابعي"], ["أبي قبيل", ""]], "athar": [68218, 68219]}, {"n": 2, "t": "بل عنى بذلك أهل الشرك", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [68221, 68224]}]}, "mawaqif": [{"taliq": 5712, "mi": 1, "aya": 69, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 362", "qawl": "الثاني", "nass": "والصواب من القول في ذلك ما قاله ابن زيد؛ وقد بين الله حقيقة ذلك بقوله: {الذين كذبوا بالكتاب وبما أرسلنا به رسلنا}", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5712, "mi": 1, "aya": 69, "alam": "ابن عطية", "fil": "رجحه", "kind": "ترجيح", "ref": "7/ 456", "qawl": "", "nass": "ظاهر الآية أنها في الكفار المجادلين في رسالة محمد صلى الله عليه وسلم والكتاب الذي جاء به، بدليل قوله: {الذين كذبوا بالكتاب}، وهذا قول ابن زيد والجمهور من المفسرين", "qawaid": ["السياق"], "tabi": "ابن جرير"}], "mushid": {"i": 11, "imgs": ["040_011_1.png"], "pages": [451], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5712, "masala": "الذين عنوا بهذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنهم أهل القدر", "ashab": "", "athar": []}, {"n": 2, "t": "أنهم أهل الشرك", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {"2": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"], "ابن عطية": ["السياق"]}, "rulesD": {}}}], "extra": [{"i": 7, "aya": 28, "imgs": ["040_007_1.png"], "pages": [450], "ihala": 0}], "others": {"0": [{"id": 5659, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (7/ 418) أن هذه السورة مكية بإجماع، ثم نقل قولًا بمدنية بعض آياتها، وانتقده، ورجَّح الأول، فقال: «وذلك ضعيف، والأول أصح». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5659, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 418", "qawl": "", "nass": "وذلك ضعيف، والأول أصح", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5660, "kinds": "تعليق،نقل", "text": "علَّق ابنُ عطية (7/ 418) على هذا الحديث بقوله: «وقفه الزَّجّاج على ابن مسعود». ثم ذكر أن معنى الديباج: «أنها خلت من الأحكام، وقُصرت على المواعظ والزجر وطرق الآخرة محضًا، وأيضًا فهي قصار، لا يلحق لقارئ فيها سآمة».", "mawaqif": [{"taliq": 5660, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 418", "qawl": "", "nass": "وقفه الزجاج على ابن مسعود", "qawaid": [], "tabi": ""}]}, {"id": 5662, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 419) أن الضَّحّاك والكسائي ذكرا أن {حم} هجاء: حُمَّ -بضم الحاء، وشد الميم المفتوحة-، ثم علَّق بقوله: «كأنه يقول: حمّ الأمر، ووقع تنزيل الكتاب من الله».", "mawaqif": [{"taliq": 5662, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 419", "qawl": "", "nass": "كأنه يقول: حم الأمر، ووقع تنزيل الكتاب من الله", "qawaid": [], "tabi": ""}]}], "4": [{"id": 5663, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 422) أن قوله: {فَلا يَغْرُرْكَ} أنزله منزلة: فلا يحزنك ولا يهمنّك. لتدل الآية على أنهم ينبغي أن لا يغتروا بإملاء الله تعالى لهم، فالخطاب له صلى الله عليه وسلم، والإشارة إلى مَن يقع منه الاغترار، ثم أورد احتمالًا آخر، فقال: «ويُحتمل أن يكون {يَغْرُرْكَ} بمعنى: تظن أن وراء تقلّبهم وإمهالهم خيرًا لهم، فتقول: عسى أن لا يُعذَّبوا».", "mawaqif": [{"taliq": 5663, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 422", "qawl": "", "nass": "ويحتمل أن يكون {يغررك} بمعنى: تظن أن وراء تقلبهم وإمهالهم خيرا لهم، فتقول: عسى أن لا يعذبوا", "qawaid": [], "tabi": ""}]}], "9": [{"id": 5664, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 425) أن قوله: {وقِهِمُ} معناه: اجعل لهم وقاية تقيهم السَّيِّئاتِ، ثم ذكر احتمالين آخرين: الأول: أن يكون الدعاء في أن يدفع الله عنهم نفس السيئات حتى لا ينالهم عذاب من أجلها. الثاني: أن يكون الدعاء في رفْع العذاب اللاحق من السيئات، فيكون في اللفظ -على هذا- حذف مضاف، كأنه قال: وقهم جزاء السيئات.", "mawaqif": [{"taliq": 5664, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 425", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "10": [{"id": 5665, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 425) هذا القول، ثم أورد احتمالًا آخر، فقال: «ويُحتمل: أن يمْقت كل واحد نفسه، فإن العبارة تحتمل المعنيين».", "mawaqif": [{"taliq": 5665, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 425", "qawl": "", "nass": "ويحتمل: أن يمقت كل واحد نفسه، فإن العبارة تحتمل المعنيين", "qawaid": [], "tabi": ""}]}], "12": [{"id": 5667, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 427) أن قوله تعالى: {ذلِكُمْ بأنه} يحتمل احتمالات عدة: الأول: أن يكون إشارة إلى العذاب الذي هم فيه. الثاني: أن يكون إشارة إلى مقْت الله إياهم. الثالث: أن يكون إشارة إلى مقْتهم أنفسهم. الرابع: أن تكون إشارة إلى المنع والزجر والإهانة المقدّرة محذوفة الذكر؛ لدلالة ظاهر القول عليها.", "mawaqif": [{"taliq": 5667, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 427", "qawl": "عليها", "nass": "", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}, {"id": 5668, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 427) أن المخاطبة بقوله تعالى: {ذلِكُمْ بأنه إذا دُعِيَ اللَّهُ وحْدَهُ كَفَرْتُمْ} تحتمل احتمالين: الأول: أن تكون المخاطَبة لمعاصري محمد صلى الله عليه وسلم في الدنيا. الثاني: أن تكون في الآخرة للكفار عامة.", "mawaqif": [{"taliq": 5668, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 427", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "15": [{"id": 5669, "kinds": "تعليق،نقل", "text": "ساق ابنُ عطية (7/ 428) قول السُّدّيّ، ثم علَّق بقوله: «كما قال تعالى: {رُوحًا مِن أمْرِنا} [الشورى: 52]، وسمى هذا: روحًا؛ لأنه يُحيي به الأمم والأزمان كما يحيي الجسد بروحه».", "mawaqif": [{"taliq": 5669, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 428", "qawl": "السدي", "nass": "كما قال تعالى: {روحا من أمرنا} [الشورى: 52]، وسمى هذا: روحا؛ لأنه يحيي به الأمم والأزمان كما يحيي الجسد بروحه", "qawaid": [], "tabi": ""}]}, {"id": 5671, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 428): «قوله: {مِن أمْرِهِ} إن جعلته جنسًا للأمور فـ {مِن} للتبعيض، أو لابتداء الغاية، وإن جعلنا الأمر من معنى الكلام فـ {مِن} إما لابتداء الغاية، وإما بمعنى الباء، ولا تكون للتبعيض بتّة».", "mawaqif": [{"taliq": 5671, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 428", "qawl": "", "nass": "قوله: {من أمره} إن جعلته جنسا للأمور ف {من} للتبعيض، أو لابتداء الغاية، وإن جعلنا الأمر من معنى الكلام ف {من} إما لابتداء الغاية، وإما بمعنى الباء، ولا تكون للتبعيض بتة", "qawaid": [], "tabi": ""}]}], "19": [{"id": 5674, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 431) أن قوله: {يَعْلَمُ خائِنَةَ الأَعْيُنِ} متصل بقوله: {سَرِيعُ الحِسابِ}؛ لأن سرعة حسابه تعالى للخلْق إنما هي بعلمه الذي لا يحتاج معه إلى رؤية وفكرة، ولا لشيء مما يحتاجه الحاسبون.\nثم ذكر أنّ فرقة قالت: {يَعْلَمُ} متصل بقوله: {لا يَخْفى عَلى اللَّهِ مِنهُمْ شَيْءٌ}، وعلَّق عليه بقوله (7/ 432): «وهذا قول حسن، يقويه تناسب المعنيين».\nثم انتقده مستندًا إلى دلالة العقل، فقال: «ويضعّفه بُعْدُ الآية من الآية، وكثرة الحائل».", "mawaqif": [{"taliq": 5674, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 431", "qawl": "", "nass": "وهذا قول حسن، يقويه تناسب المعنيين", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}, {"id": 5675, "kinds": "تعليق،نقل", "text": "ذكر ابن عطية (7/ 432) أن ما ذكره المفسرون في هذه الآية من نظر الرجل إلى امرأة هي حُرمة لغيره، وما قالوه من أن خائنة الأعين: هي النظرة الثانية. وما تخفي الصدور: أي عند النظرة الأولى التي لا يمكن المرء دفعها، هو مثال، ثم علَّق بقوله: «وهذا المثال جزء من خائنة الأعين».", "mawaqif": [{"taliq": 5675, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 432", "qawl": "", "nass": "وهذا المثال جزء من خائنة الأعين", "qawaid": [], "tabi": ""}]}], "20": [{"id": 5676, "kinds": "بيان،تعليق", "text": "علَّق ابنُ كثير (12/ 182) على قول ابن عباس، بقوله: «وهذا الذي فسّره ابن عباس في هذه الآية كقوله تعالى: {ليجزي الذين أساءوا بما عملوا ويجزي الذين أحسنوا بالحسنى} [النجم: 31]».", "mawaqif": [{"taliq": 5676, "mi": 0, "aya": 20, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "12/ 182", "qawl": "ابن عباس", "nass": "وهذا الذي فسره ابن عباس في هذه الآية كقوله تعالى: {ليجزي الذين أساءوا بما عملوا ويجزي الذين أحسنوا بالحسنى} [النجم: 31]", "qawaid": [], "tabi": ""}]}], "28": [{"id": 5681, "kinds": "تعليق", "text": "علَّق ابنُ كثير (12/ 187) على هذا الأثر بقوله: «رواه النسائي من حديث عبدة، فجعله من مسند عمرو بن العاص».", "mawaqif": [{"taliq": 5681, "mi": 0, "aya": 28, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "12/ 187", "qawl": "", "nass": "رواه النسائي من حديث عبدة، فجعله من مسند عمرو بن العاص", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5682, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (7/ 439) عن أبي حاتم أنه قال: «كان معاذ بن جبل يفسر قوله: {سبيل الرشاد} بسبيل الله».\nوانتقده مستندًا إلى الدلالة العقلية، واللغة، فقال: «ويبعد عندي هذا على معاذ?، وهل كان فرعون يدعي إلا أنه إله؟ ويقلق بناء اللفظة على هذا التأويل».", "mawaqif": [{"taliq": 5682, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 439", "qawl": "", "nass": "كان معاذ بن جبل يفسر قوله: {سبيل الرشاد} بسبيل الله", "qawaid": ["الدلالة العقلية", "اللغة"], "tabi": ""}]}], "34": [{"id": 5687, "kinds": "تعليق،نقل", "text": "علَّق ابنُ عطية (4/ 12 - 13) على هذا القول بقوله: «ومَن قال: إنّ يوسف المبعوث الذي أشار إليه موسى في قوله: {ولقد جاءكم يوسف من قبل بالبينات} هو غير يوسف الصّدِّيق. فليس يحتاج إلى نظر، ومَن قال: إنه يوسف الصديق. فيعارضه ما يظهر من قصة يوسف، وذلك أنّه ملَكَ مصر بعد عزيزها، فكيف يستقيم أن يعيش عزيزُها إلى مدة موسى، فينفصل أنّ العزيز ليس بفرعون الملك، إنما كان حاجبًا له».", "mawaqif": [{"taliq": 5687, "mi": 0, "aya": 34, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "4/ 12 - 13", "qawl": "بقوله", "nass": "ومن قال: إن يوسف المبعوث الذي أشار إليه موسى في قوله: {ولقد جاءكم يوسف من قبل بالبينات} هو غير يوسف الصديق. فليس يحتاج إلى نظر، ومن قال: إنه يوسف الصديق. فيعارضه ما يظهر من قصة يوسف، وذلك أنه ملك مصر بعد عزيزها، فكيف يستقيم أن يعيش عزيزها إلى مدة موسى، فينفصل أن العزيز ليس بفرعون الملك، إنما كان حاجبا له", "qawaid": [], "tabi": ""}]}], "36": [{"id": 5689, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 443) أنه روي: أن هامان لم يكن من القِبط. وأنه قيل: إنه كان منهم.", "mawaqif": [{"taliq": 5689, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 443", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5690, "kinds": "خلاف،ترجيح،نقل", "text": "اختُلف في قراءة قوله: {فأطلع}؛ فقرأ قوم بضم العين، وقرأ غيرهم بنصبها.\nوذكر ابنُ جرير (20/ 326) أن الأولى ردًّا على قوله: {أبلغ الأسباب}، وعطفًا به عليه، وأن الثانية جاءت نصبًا جوابًا لـ «لعل».\nوبنحوه قال ابنُ عطية (7/ 443).\nورجَّح ابنُ جرير (20/ 327) الأولى مستندًا إلى إجماع القراء، فقال: «والقراءة التي لا أستجيزُ غيرَها الرفعُ في ذلك؛ لإجماع الحُجَّة مِن القُرّاء عليه».", "mawaqif": [{"taliq": 5690, "mi": 0, "aya": 36, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 326", "qawl": "", "nass": "لعل", "qawaid": [], "tabi": ""}, {"taliq": 5690, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 443", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5690, "mi": 0, "aya": 36, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 327", "qawl": "", "nass": "والقراءة التي لا أستجيز غيرها الرفع في ذلك؛ لإجماع الحجة من القراء عليه", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}]}], "37": [{"id": 5692, "kinds": "خلاف،ترجيح،توجيه،تعليق،نقل", "text": "اختُلف في قراءة قوله: {وصد عن السبيل}؛ فقرأ قوم بضم الصاد، وقرأ غيرهم بفتحها.\nوذكر ابنُ جرير (20/ 327 - 328) أن الأولى على وجه ما لم يُسم فاعله، وأن الثانية بمعنى: وأعرض فرعون عن سبيل الله التي ابتعث بها موسى استكبارًا.\nوذكر ابنُ عطية (7/ 444) أن القراءة بضم الصاد وفتح الدال المشددة عطفًا على {زُيِّنَ} وحملًا عليه.\nوبنحوهما قال ابنُ القيم (2/ 408 - 409).\nوذكر ابنُ القيم أن «صَدّ» بالفتح تحتمل: أعرض؛ فيكون لازمًا، وتحتمل أن يكون: صد غيره؛ فيكون متعدّيًا.\nورجَّح ابنُ جرير (20/ 328) صحة كلتا القراءتين مستندًا إلى شهرتهما، فقال: «والصواب من القول في ذلك أن يقال: إنهما قراءتان معروفتان في قراءة الأمصار، فبأيتهما قرأ القارئ فمصيب».\nوعلَّق ابنُ القيم (2/ 409) على القراءتين بقوله: «والقراءتان كالآيتين، لا يتناقضان».", "mawaqif": [{"taliq": 5692, "mi": 0, "aya": 37, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 327 - 328", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5692, "mi": 0, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 444", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5692, "mi": 0, "aya": 37, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 408 - 409", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 5692, "mi": 0, "aya": 37, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "صد", "qawaid": [], "tabi": ""}, {"taliq": 5692, "mi": 0, "aya": 37, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 328", "qawl": "", "nass": "والصواب من القول في ذلك أن يقال: إنهما قراءتان معروفتان في قراءة الأمصار، فبأيتهما قرأ القارئ فمصيب", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 5692, "mi": 0, "aya": 37, "alam": "ابن القيم", "fil": "علق", "kind": "تعليق", "ref": "2/ 409", "qawl": "", "nass": "والقراءتان كالآيتين، لا يتناقضان", "qawaid": [], "tabi": ""}]}, {"id": 5693, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (7/ 444) أنّ التباب: الخسران، ومنه: {تَبَّتْ يَدا أبِي لَهَبٍ} [المسد: 1]، ثم قال: «وبه فسّر مجاهد، وقتادة. وتبُّ فرعون ظاهر؛ لأنه خسِر مالَه في الصرح وغيره، وخسر مُلكَه، وخسر نفسه، وخلد في جهنم».", "mawaqif": [{"taliq": 5693, "mi": 0, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 444", "qawl": "", "nass": "وبه فسر مجاهد، وقتادة. وتب فرعون ظاهر؛ لأنه خسر ماله في الصرح وغيره، وخسر ملكه، وخسر نفسه، وخلد في جهنم", "qawaid": [], "tabi": ""}]}], "38": [{"id": 5694, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 444) أن قوله: {اتَّبِعُونِ أهْدِكُمْ} يقوّي أن المتكلم موسى عليه السلام، ثم قال: «وإن كان الآخر يحتمل أن يقول ذلك، أي: اتبعوني في اتباعي موسى عليه السلام».", "mawaqif": [{"taliq": 5694, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 444", "qawl": "", "nass": "وإن كان الآخر يحتمل أن يقول ذلك، أي: اتبعوني في اتباعي موسى عليه السلام", "qawaid": [], "tabi": ""}]}], "43": [{"id": 5695, "kinds": "تعليق،نقل", "text": "ساق ابنُ كثير (12/ 193) هذا القول، ثم علَّق بقوله: «وهذا كقوله تعالى: {ومن أضل ممن يدعو من دون الله من لا يستجيب له إلى يوم القيامة وهم عن دعائهم غافلون. وإذا حشر الناس كانوا لهم أعداء وكانوا بعبادتهم كافرين} [الأحقاف: 5 - 6]، {إن تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم} [فاطر: 14]».", "mawaqif": [{"taliq": 5695, "mi": 0, "aya": 43, "alam": "ابن كثير", "fil": "ساق", "kind": "نقل", "ref": "12/ 193", "qawl": "", "nass": "وهذا كقوله تعالى: {ومن أضل ممن يدعو من دون الله من لا يستجيب له إلى يوم القيامة وهم عن دعائهم غافلون. وإذا حشر الناس كانوا لهم أعداء وكانوا بعبادتهم كافرين} [الأحقاف: 5 - 6]، {إن تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم} [فاطر: 14]", "qawaid": [], "tabi": ""}]}], "45": [{"id": 5697, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 446) أن الضمير في قوله: {فَوَقاهُ} يحتمل أن يعود على موسى، ويحتمل أن يعود على مؤمن آل فرعون.", "mawaqif": [{"taliq": 5697, "mi": 0, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 446", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "46": [{"id": 5698, "kinds": "بيان،تعليق", "text": "علَّق ابنُ عطية (7/ 447) على قول القرظي بأنه: «أراد: أنهم يُعرضون في الآخرة على النار على تقدير ما بين الغدو والعشي؛ إذ لا غدو ولا عشي في الآخرة، وإنما ذلك على التقدير بأيام الدنيا».", "mawaqif": [{"taliq": 5698, "mi": 0, "aya": 46, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 447", "qawl": "القرظي بأنه", "nass": "أراد: أنهم يعرضون في الآخرة على النار على تقدير ما بين الغدو والعشي؛ إذ لا غدو ولا عشي في الآخرة، وإنما ذلك على التقدير بأيام الدنيا", "qawaid": [], "tabi": ""}]}, {"id": 5701, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 447) أن قوله: {ويَوْمَ تَقُومُ السّاعَةُ} يحتمل أن يكون «يَوْمَ» عطفًا على «عَشِيًّا»، والعامل فيه {يُعْرَضُونَ}. ويحتمل أن يكون كلامًا مقطوعًا والعامل في «يَوْمَ» {أدْخِلُوا}، ثم قال: «والتقدير: على كل قول: يقال أدخلوا».\nوذكر ابنُ القيم (2/ 409) أن الصحيح في لفظة «الآل»: أنهم الأتباع.", "mawaqif": [{"taliq": 5701, "mi": 0, "aya": 46, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 447", "qawl": "", "nass": "يوم", "qawaid": [], "tabi": ""}, {"taliq": 5701, "mi": 0, "aya": 46, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 409", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "50": [{"id": 5702, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 448) أن فرقة قالت: إن قوله تعالى: {وما دُعاءُ الكافِرِينَ إلّا فِي ضَلالٍ} هو من قول الخزنة. وأن فرقة أخرى قالت: هو من قول الله تعالى إخبارًا منه لمحمد صلى الله عليه وسلم.", "mawaqif": [{"taliq": 5702, "mi": 0, "aya": 50, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 448", "qawl": "الخزنة", "nass": "", "qawaid": [], "tabi": ""}]}], "51": [{"id": 5703, "kinds": "نقد،بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 448 - 449) أن بعض المفسرين ذهب إلى أن قوله: {إنا لننصر رسلنا} خاصٌّ فيمَن أظهره الله على أمته كنوح وموسى ومحمد، وليس بعامٍّ؛ لأنّا نجد من الأنبياء مَن قتله قومه؛ كيحيى، ولم يُنصر عليهم، وبيّن أنه على قول السُّدّيّ فالخبر عامٌّ على وجهه، وذلك أن نُصرة الرسل واقعة ولا بُدَّ، إما في حياة الرسول المنصور كنوح وموسى، وإما فيما يأتي من الزمان بعد موته.\nثم علَّق على قول السُّدّيّ بقوله: \"ألا ترى إلى ما صنع الله ببني إسرائيل بعد قتلهم يحيى عليه السلام مِن تسليط بختنصر عليهم، حتى انتصر ليحيى عليه السلام، ونصْر المؤمنين داخل في نصر الرسل عليه السلام، وأيضًا فقد جعل الله للمؤمنين الفضلاء ودًّا، ووهبهم نصرًا إذ ظُلموا، وحضّت الشريعة على نُصرتهم، ومنه قول النبي صلى الله عليه وسلم: «مَن ردَّ عن أخيه المسلم في عِرضه كان حقًّا على الله أن يرد عنه نار جهنم». وقوله صلى الله عليه وسلم: «مَن حمى مؤمنًا مِن منافق يغتابه بعث الله مَلكًا يحميه يوم القيامة».\nوبنحوه قال ابنُ جرير (20/ 345).", "mawaqif": [{"taliq": 5703, "mi": 0, "aya": 51, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 448 - 449", "qawl": "السدي فالخبر", "nass": "من رد عن أخيه المسلم في عرضه كان حقا على الله أن يرد عنه نار جهنم", "qawaid": [], "tabi": ""}, {"taliq": 5703, "mi": 0, "aya": 51, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "20/ 345", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 5705, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 449) أن الأشهاد يحتمل أن يكون من الشهادة، ويحتمل أن يكون من المشاهدة بمعنى المصدر.", "mawaqif": [{"taliq": 5705, "mi": 0, "aya": 51, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 449", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "55": [{"id": 5706, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ جرير (20/ 348) أن الإبكار هو مِن طلوع الفجر الثاني إلى طلوع الشمس، ثم ذكر قولًا آخر، وهو: أنه من طلوع الشمس إلى ارتفاع الضحى، وخروج وقت الضحى.\nورجَّح الأولَ مستندًا إلى المعروف في لغة العرب، فقال: «والمعروف عند العرب القول الأول».", "mawaqif": [{"taliq": 5706, "mi": 0, "aya": 55, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 348", "qawl": "", "nass": "والمعروف عند العرب القول الأول", "qawaid": ["اللغة"], "tabi": ""}]}], "56": [{"id": 5707, "kinds": "نقد", "text": "انتقد ابنُ كثير (12/ 201) هذا القول الذي قاله كعب، وأبو العالية بقوله: «وهو قول غريب، وفيه تعسُّف بعيد، وإن كان قد رواه أبي حاتم في كتابه».", "mawaqif": [{"taliq": 5707, "mi": 0, "aya": 56, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "12/ 201", "qawl": "", "nass": "وهو قول غريب، وفيه تعسف بعيد، وإن كان قد رواه أبي حاتم في كتابه", "qawaid": [], "tabi": ""}]}, {"id": 5708, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (7/ 450) أن الاستعاذة بالله التي أُمر بها النبي صلى الله عليه وسلم عامة في كل أمره من كل مستعاذ منه، ونقل عن الثعلبي أنه قال: «هذه الاستعاذة هي من الدَّجّال وفتنته».\nورجَّح العموم، فقال: «والأظهر ما قدّمناه من العموم في كل مُستعاذ منه».", "mawaqif": [{"taliq": 5708, "mi": 0, "aya": 56, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 450", "qawl": "", "nass": "هذه الاستعاذة هي من الدجال وفتنته", "qawaid": [], "tabi": ""}]}], "57": [{"id": 5709, "kinds": "ترجيح،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 451) أن قوله تعالى: {لَخَلْقُ السَّماواتِ والأَرْضِ أكْبَرُ مِن خَلْقِ النّاسِ} توبيخ لهؤلاء الكفرة المتكبّرين، كأنه قال: مخلوقات الله أكبر وأجل قدْرًا من خلق البشر، فما لأحد منهم أن يتكبّر على خالقه. ثم ساق احتمالًا آخر، فقال: «ويحتمل أن يكون الكلام في معنى البعث والإعادة، فأعلم أن الذي خلق السماوات والأرض قوي قادر على خلق الناس تارة أخرى». وعلَّق عليه بقوله: «والخَلْقُ -على هذا التأويل- مصدر مضاف إلى المفعول».\nونقل عن النقاش أنه قال: «المعنى: مما يخلق الناس؛ إذ هم في الحقيقة لا يخلقون شيئًا». وعلَّق عليه بقوله: «فالخلق في قوله: {مِن خَلْقِ النّاسِ} مضاف إلى الفاعل على هذا التأويل».", "mawaqif": [{"taliq": 5709, "mi": 0, "aya": 57, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 451", "qawl": "", "nass": "ويحتمل أن يكون الكلام في معنى البعث والإعادة، فأعلم أن الذي خلق السماوات والأرض قوي قادر على خلق الناس تارة أخرى", "qawaid": [], "tabi": ""}]}], "60": [{"id": 5710, "kinds": "ترجيح،توجيه،بيان،نقل", "text": "قوله تعالى: {ادعوني استجبْ لكم} فيه ثلاثة أقوال: الأول: وحدوني أغفر لكم. الثاني: اعبدوني استجب لكم. الثالث: سَلُوني أعطكم. وبيّن ابنُ عطية (7/ 452) أن الاستجابة بمعنى إجابة الدعاء مقيّدة بالمشيئة، ثم ذكر أن فرقة قالت: معنى: {أسْتَجِبْ}: بالثواب والنصر.\nووجّه من قال: إن الدعاء هو العبادة بالسياق والسنة، فقال: «ويدل على هذا التأويل قوله: {إنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبادَتِي}، ويُحتج له بحديث النعمان بن بشير أن النبي صلى الله عليه وسلم قال: «الدعاء هو العبادة»».\nوذكر ابنُ تيمية (5/ 447) أن الدعاء يتضمن دعاء العبادة، والمسألة، ثم رجَّح كونه دعاء عبادة مستندًا إلى السياق، قال: «وهو في العبادة أظهر؛ ولهذا أعقبه: {إن الذين يستكبرون عن عبادتي} الآية. ويُفسر الدعاء بهذا وهذا».", "mawaqif": [{"taliq": 5710, "mi": 0, "aya": 60, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 452", "qawl": "", "nass": "ويدل على هذا التأويل قوله: {إن الذين يستكبرون عن عبادتي}، ويحتج له بحديث النعمان بن بشير أن النبي صلى الله عليه وسلم قال: «الدعاء هو العبادة»", "qawaid": [], "tabi": ""}, {"taliq": 5710, "mi": 0, "aya": 60, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 447", "qawl": "", "nass": "وهو في العبادة أظهر؛ ولهذا أعقبه: {إن الذين يستكبرون عن عبادتي} الآية. ويفسر الدعاء بهذا وهذا", "qawaid": ["السياق"], "tabi": ""}]}], "70": [{"id": 5713, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 456) أن «الذين» ابتداء وخبره: {فَسَوْفَ يَعْلَمُونَ}، ثم ساق احتمالًا آخر، فقال: «ويحتمل أن يكون خبر الابتداء محذوفًا، والفاء متعلقة به».", "mawaqif": [{"taliq": 5713, "mi": 0, "aya": 70, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 456", "qawl": "", "nass": "الذين", "qawaid": [], "tabi": ""}]}], "71": [{"id": 5714, "kinds": "خلاف،ترجيح،نقل", "text": "اختُلف في قراءة قوله: {والسلاسل يسحبون}؛ فقرأ قوم: {والسلاسلُ} بالرفع. وقرأ غيرهم بنصبها وفتح {يسحبون}.\nوذكر ابنُ جرير (20/ 363) أن الأولى جاءت بالرفع عطفًا على {الأغلال}. وأن القراءة الثانية بمعنى: ويسحبون السلاسل.\nوبنحوه قال ابنُ عطية (7/ 456).\nورجَّح ابنُ جرير (20/ 364) قراءة الرفع مستندًا إلى إجماع القراء، فقال: «والصواب من القراءة عندنا في ذلك ما عليه قراء الأمصار؛ لإجماع الحجة عليه، وهو رفع» السلاسل «عطفًا بها على ما في قوله: {في أعناقهم} من ذكر الأغلال».", "mawaqif": [{"taliq": 5714, "mi": 0, "aya": 71, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 363", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5714, "mi": 0, "aya": 71, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 456", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5714, "mi": 0, "aya": 71, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 364", "qawl": "", "nass": "والصواب من القراءة عندنا في ذلك ما عليه قراء الأمصار؛ لإجماع الحجة عليه، وهو رفع", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}]}], "72": [{"id": 5715, "kinds": "تعليق،نقل", "text": "ساق ابنُ عطية (7/ 457) هذا القول، ثم علَّق بقوله: «والعرب تقول: سجرت التنّور: إذا ملأتها».", "mawaqif": [{"taliq": 5715, "mi": 0, "aya": 72, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 457", "qawl": "", "nass": "والعرب تقول: سجرت التنور: إذا ملأتها", "qawaid": [], "tabi": ""}]}], "78": [{"id": 5716, "kinds": "توجيه،نقل", "text": "وجَّه ابنُ عطية (7/ 458) هذا القول، بقوله: «وهذا إنما ساقه على أن هذا الحبشي مثال لمن لم يقصّ، لا أنه هو المقصود وحده؛ فإن هذا بعيد».", "mawaqif": [{"taliq": 5716, "mi": 0, "aya": 78, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 458", "qawl": "", "nass": "وهذا إنما ساقه على أن هذا الحبشي مثال لمن لم يقص، لا أنه هو المقصود وحده؛ فإن هذا بعيد", "qawaid": [], "tabi": ""}]}, {"id": 5717, "kinds": "نقل", "text": "ذكر ابنُ عطية أن قوله: {فَإذا جاءَ أمْرُ اللَّهِ} معناه: إذا أراد الله إرسال رسول وبعثة نبي قضى ذلك وأنفذه بالحق، وخسر كل مبطل، وحصل على فساد آخرته. ثم أورد احتمالًا آخر، فقال: «وتحتمل الآية معنى آخر، وهو أن يريد بـ {أمْرُ اللَّهِ}: القيامة؛ فتكون الآية توعُّدًا لهم بالآخرة».", "mawaqif": [{"taliq": 5717, "mi": 0, "aya": 78, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وتحتمل الآية معنى آخر، وهو أن يريد ب {أمر الله}: القيامة؛ فتكون الآية توعدا لهم بالآخرة", "qawaid": [], "tabi": ""}]}], "83": [{"id": 5718, "kinds": "تعليق،نقل", "text": "ساق ابنُ عطية (7/ 460) قولَ مجاهد، ثم علَّق بقوله: «أي: بما عندهم من العلم في ظنهم ومعتقدهم من أنهم لا يُبعثون ولا يُحاسبون». وذكر أنّ ابن زيد قال: واغتروا بعلمهم في الدنيا والمعايش، وظنوا أنه لا آخرة ففرحوا. وعلَّق عليه بقوله: «وهذا كقوله تعالى: {يَعْلَمُونَ ظاهِرًا مِنَ الحَياةِ الدُّنْيا} [الروم: 7]».", "mawaqif": [{"taliq": 5718, "mi": 0, "aya": 83, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 460", "qawl": "مجاهد", "nass": "أي: بما عندهم من العلم في ظنهم ومعتقدهم من أنهم لا يبعثون ولا يحاسبون", "qawaid": [], "tabi": ""}]}, {"id": 5719, "kinds": "تعليق،نقل", "text": "أفادت الآثارُ أنّ الضمير في قوله: {فرحوا} عائد على الأمم المذكورين، وهو ما ذكره ابنُ عطية (7/ 460)، وساق قولًا غيره بعودة الضمير على الرسل، وعلَّق عليه بقوله: «وفي هذا التأويل حذفٌ، تقديره: كذبوهم، ففرحوا -أي: الرسل- بما عندهم من العلم بالله، والثقة به، وبأنه سينصرهم».", "mawaqif": [{"taliq": 5719, "mi": 0, "aya": 83, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 460", "qawl": "", "nass": "وفي هذا التأويل حذف، تقديره: كذبوهم، ففرحوا -أي: الرسل- بما عندهم من العلم بالله، والثقة به، وبأنه سينصرهم", "qawaid": [], "tabi": ""}]}]}, "athar": {"68096": {"num": 68096, "aya": 43, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وأَنَّ المُسْرِفِينَ هُمْ أصْحابُ النّارِ}، قال: سمّاهم الله: مسرفين؛ فرعون ومَن معه."}, "68224": {"num": 68224, "aya": 69, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {أنّى يُصْرَفُون}، قال: يُصرَفون عن الحق."}, "67983": {"num": 67983, "aya": 28, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {وقالَ رَجُلٌ مُؤْمِنٌ مِن آلِ فِرْعَوْنَ}، قال: هو ابن عمِّ فرعون، ويقال: هو الذي نجا مع موسى."}, "68111": {"num": 68111, "aya": 46, "qail": "الهزيل بن شرحبيل", "tabaqa": "", "bab": "", "text": "عن الهُزَيْل بن شُرَحْبِيل -من طريق أبي قيس الأودي- قال: إنّ أرواح آل فرعون في أجواف طير سُود، تغدو وتروح على النار، فذلك عرْضها، وأرواح الشهداء في أجواف طير خُضر، وأولاد المسلمين الذين لم يبلغوا الحِنث، عصافير الجنة ترعى وتسْرح."}, "68112": {"num": 68112, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {يُعْرَضُونَ عَلَيْها غُدُوًّا وعَشِيًّا}، قال: ما كانت الدنيا تُعْرَضُ أرواحُهم."}, "68117": {"num": 68117, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {النّارُ يُعْرَضُونَ عَلَيْها غُدُوًّا وعَشِيًّا}، قال: صباحًا ومساء، يُقال لهم: آلَ فرعونَ، هذه منازلكم، فانظروا إليها. توبيخًا، ونِقمة، وصَغارًا."}, "68118": {"num": 68118, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة ="}, "67991": {"num": 67991, "aya": 28, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {إنَّ اللَّهَ لا يَهْدِي مَن هُوَ مُسْرِفٌ كَذّابٌ}، قال: المشرك أسرفَ على نفسه بالشرك."}, "67992": {"num": 67992, "aya": 28, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "قال إسماعيل السُّدّيّ: {مُسْرِفٌ} قتّال."}, "67993": {"num": 67993, "aya": 28, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {إنَّ اللَّهَ لا يَهْدِي مَن هُوَ مُسْرِفٌ كَذّابٌ}، قال: المسرف: هو صاحب الدّم. ويقال: هم المشركون."}, "68120": {"num": 68120, "aya": 46, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- قال: {النّارُ يُعْرَضُونَ عَلَيْها غُدُوًّا وعَشِيًّا}، بلغني: أنّ أرواح قوم فرعون في أجواف طير سُود، تُعرَض على النار غُدُوًّا وعَشِيًّا، حتى تقوم الساعة."}, "68219": {"num": 68219, "aya": 69, "qail": "أبي قبيل", "tabaqa": "", "bab": "", "text": "عن أبي قبيل، قال: أخبرني عقبة بن عامر الجهني أنّ رسول الله صلى الله عليه وسلم قال: «سيهْلَك مِن أمتي أهل الكتاب، وأهل اللَّبَن». فقال عقبة: يا رسول الله، وما أهل الكتاب؟ قال: «قوم يتعلّمون كتاب الله يجادلون الذين آمنوا». فقال عقبة: يا رسول الله، وما أهل اللَّبَن؟ قال: «قوم يتّبعون الشهوات، ويضيِّعون الصلوات». قال أبو قبيل: لا أحسب المكذِّبين بالقَدَر إلّا الذين يجادلون الذين آمنوا، وأما أهل اللَّبَن فلا أحسبهم إلّا أهل العمود، ليس عليهم إمام جماعة، ولا يعرفون شهر رمضان."}, "67903": {"num": 67903, "aya": 15, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق جويبر- في قوله: {يُلْقِي الرُّوحَ مِن أمْرِهِ عَلى مَن يَشاءُ مِن عِبادِهِ}، قال: يعني بالروح: الكتاب، يُنزله على مَن يشاء."}, "67904": {"num": 67904, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {يُلْقِي الرُّوحَ}، قال: الوحيُ، والرحمة."}, "67905": {"num": 67905, "aya": 15, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- في قول الله: {يُلْقِي الرُّوحَ مِن أمْرِهِ عَلى مَن يَشاءُ مِن عِبادِهِ}، قال: النبوة على من يشاء."}, "67907": {"num": 67907, "aya": 15, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {يُلْقِي الرُّوحَ مِن أمْرِهِ عَلى مَن يَشاءُ مِن عِبادِهِ}، وقرأ: {وكَذَلِكَ أوْحَيْنا إلَيْكَ رُوحًا مِن أمْرِنا} [الشورى: 52]، قال: هذا القرآن هو الروح، أوحاه الله إلى جبريل، وجبريل روحٌ نزل به على النبي صلى الله عليه وسلم. وقرأ: {نَزَلَ بِهِ الرُّوحُ الأَمِينُ} [الشعراء: 193]، قال: فالكُتب التي أنزلها الله على أنبيائه هي الروح، ليُنذر بها ما قال الله يوم التَّلاق، {يَوْمَ يَقُومُ الرُّوحُ والمَلائِكَةُ صَفًّا} [النبأ: 38]، قال: الروح؛ القرآن. كان أبي يقوله. قال ابن زيد: يقومون له صفًّا بين السماء والأرض، حين ينزل جل جلاله."}, "67915": {"num": 67915, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {لِيُنْذِرَ يَوْمَ التَّلاقِ}، قال: يوم يتلاقى أهل السماء وأهل الأرض، والخالق وخلْقه."}, "67916": {"num": 67916, "aya": 15, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {لِيُنْذِرَ يَوْمَ التَّلاقِ}: يلتقي أهل السماء وأهل الأرض."}, "67918": {"num": 67918, "aya": 15, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {يَوْمَ التَّلاقِ}، قال: يوم القيامة. قال: يوم تتلاقى العباد."}, "68048": {"num": 68048, "aya": 36, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وقالَ فِرْعَوْنُ يا هامانُ ابْنِ لِي صَرْحًا}، قال: كان أولَ مَن بنى بهذا الآجُرّ وطبخه."}, "68052": {"num": 68052, "aya": 36, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عطية- في قوله: {لَعَلِّي أبْلُغُ الأَسْبابَ أسْبابَ السَّماواتِ}، قال: مَنزِل السماء."}, "68053": {"num": 68053, "aya": 36, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن أبي صالح باذام -من طريق السُّدّيّ- في قوله: {أسْبابَ السَّماواتِ}، قال: طُرُق السماوات."}, "68054": {"num": 68054, "aya": 36, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن قتادة بن دعامة -من طريق سعيد- {لَعَلِّي أبْلُغُ الأَسْبابَ} قال: الأبواب، {أسْبابَ السَّماواتِ} أي: أبواب السماوات."}, "68055": {"num": 68055, "aya": 36, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {أبْلُغُ الأَسْبابَ أسْبابَ السَّماواتِ}، قال: طرق السموات."}, "67800": {"num": 67800, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس، مثله."}, "67804": {"num": 67804, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {ذِي الطَّوْلِ}، قال: ذي السَّعة والغِنى."}, "67805": {"num": 67805, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: {ذِي الطَّوْل} ذي الغنى عَمَّن لا يقول: لا إله إلا الله."}, "67807": {"num": 67807, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قول الله: {ذِي الطَّوْلِ}، قال: ذي الغِنى."}, "67808": {"num": 67808, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قول الله: {ذِي الطَّوْلِ}: ذي إنعام."}, "67812": {"num": 67812, "aya": 3, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {ذِي الطَّوْلِ}، قال: ذي النِّعَم."}, "67815": {"num": 67815, "aya": 3, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله {ذِي الطَّوْلِ}، قال: الطول: القدرة، ذاك الطول."}, "67816": {"num": 67816, "aya": 3, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن قتادة بن دعامة، قال: كان شابٌّ بالمدينة صاحبَ عبادة، وكان عمرُ مُعجبًا به، فانطلق إلى مصر، فَفَسُد، فجعل لا يمتنع عن شرٍّ، فقدم على عمر بعضُ أهله، فسأله حتى سأله عن الشابّ، فقال: لا تسألني عنه. قال: لِمَ؟ قال: إنّه فسد وخلع. فكتب إليه عمر: مِن عمر إلى فلان، {حم تَنْزِيلُ الكِتابِ مِنَ اللَّهِ العَزِيزِ العَلِيمِ غافِرِ الذَّنْبِ وقابِلِ التَّوْبِ شَدِيدِ العِقابِ ذِي الطَّوْلِ لا إلَهَ إلّا هُوَ إلَيْهِ المَصِيرُ}. فجعل يقترئها على نفسه، فأقبل بخير."}, "68083": {"num": 68083, "aya": 43, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {لا جَرَمَ أنَّما تَدْعُونَنِي إلَيْهِ لَيْسَ لَهُ دَعْوَةٌ فِي الدُّنْيا}، قال: الوَثَن ليس بشيء."}, "68084": {"num": 68084, "aya": 43, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {لَيْسَ لَهُ دَعْوَةٌ فِي الدُّنْيا ولا فِي الآخِرَةِ}، قال: لا يضُرُّ، ولا ينفع."}, "68085": {"num": 68085, "aya": 43, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {لَيْسَ لَهُ دَعْوَةٌ فِي الدُّنْيا} ليست له دعوة مستجابة."}, "68218": {"num": 68218, "aya": 69, "qail": "محمد بن سيرين", "tabaqa": "تابعي", "bab": "", "text": "عن محمد بن سيرين -من طريق داود بن أبي هند- قال: إن لم تكن هذه الآية نزلت في القَدَرية فإني لا أدري فيمن نزلت: {ألَمْ تَرَ إلى الَّذِينَ يُجادِلُونَ فِي آياتِ اللَّهِ أنّى يُصْرَفُونَ} إلى قوله: {لَمْ نَكُنْ نَدْعُو مِن قَبْلُ شَيْئًا كَذَلِكَ يُضِلُّ اللَّهُ الكافِرِين}."}, "68091": {"num": 68091, "aya": 43, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وأَنَّ المُسْرِفِينَ} السّفّاكين للدماء بغير حقّها {هُمْ أصْحابُ النّارِ}."}, "68221": {"num": 68221, "aya": 69, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ألَمْ تَرَ إلى الَّذِينَ يُجادِلُونَ فِي آياتِ اللَّهِ أنّى يُصْرَفُونَ}، قال: هؤلاء المشركون."}, "68094": {"num": 68094, "aya": 43, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {وأَنَّ المُسْرِفِينَ هُمْ أصْحابُ النّارِ}، قال: المشركين."}}, "n_athar": {"0": 39, "2": 1, "3": 20, "4": 9, "5": 9, "6": 5, "7": 25, "8": 3, "9": 2, "10": 8, "11": 13, "12": 3, "13": 3, "14": 2, "15": 19, "16": 11, "17": 4, "18": 15, "19": 10, "20": 3, "21": 2, "22": 1, "23": 3, "25": 3, "26": 6, "27": 1, "28": 21, "29": 3, "30": 2, "31": 6, "32": 14, "33": 8, "34": 6, "35": 7, "36": 11, "37": 9, "38": 1, "39": 4, "40": 8, "41": 3, "42": 1, "43": 14, "44": 4, "45": 5, "46": 20, "47": 2, "48": 1, "49": 3, "50": 2, "51": 15, "52": 1, "53": 1, "54": 1, "55": 6, "56": 13, "57": 3, "58": 2, "59": 1, "60": 23, "61": 1, "62": 1, "64": 3, "65": 3, "66": 3, "67": 6, "68": 1, "69": 7, "70": 1, "71": 8, "72": 7, "73": 2, "75": 4, "76": 1, "77": 2, "78": 6, "79": 1, "80": 4, "81": 1, "82": 2, "83": 3, "84": 3, "85": 5}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});